def process_file(filepath):
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()
    
    modified = False
    for emj, svg in svg_map.items():
        if emj in content:
            content = content.replace(emj, svg)
            modified = True
            
    # Also replace "🔍 " with SVG in placeholders, actually placeholder="🔍 Buscar..." can't have SVG
    # We must keep text placeholders without SVG. Wait, I'll revert replacing inside placeholder="" using regex if needed, 
    # but simplest is to just manually fix placeholders or remove emojis from placeholders.
    # I'll just remove emojis from placeholders.
    content = re.sub(r'placeholder="[^"]*"', lambda m: m.group(0).replace('🔍 ', ''), content)
    
    if modified:
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"Updated {filepath}")

base_dir = r"c:\Users\medin\OneDrive\Escritorio\DreamBake\src\main\resources"
for root, dirs, files in os.walk(base_dir):
    for f in files:
        if f.endswith(".html") or f.endswith(".js"):
            process_file(os.path.join(root, f))
